<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Document;use Illuminate\Http\Request;class DocumentController extends Controller{public function index(){return view('admin.documents.index',['items'=>Document::orderBy('category')->orderBy('sort')->paginate(40)]);}public function create(){return view('admin.documents.form',['item'=>new Document]);}public function store(Request $r){Document::create($this->data($r));return redirect()->route('admin.documents.index')->with('ok','Документ добавлен');}public function edit(Document $document){return view('admin.documents.form',['item'=>$document]);}public function update(Request $r,Document $document){$document->update($this->data($r,$document));return redirect()->route('admin.documents.index')->with('ok','Сохранено');}public function destroy(Document $document){$document->delete();return back();}private function data(Request $r,?Document $item=null){$rules=['title'=>'required|max:255','category'=>'required|max:255','published_at'=>'nullable|date','sort'=>'nullable|integer','file'=>($item?'nullable':'required').'|file|max:20480|mimes:pdf,doc,docx,xls,xlsx'];$d=$r->validate($rules);if($r->hasFile('file'))$d['file']=$r->file('file')->store('documents','public');else unset($d['file']);$d['is_published']=$r->boolean('is_published');return $d;}}